window.__votdWeek && window.__votdWeek({"week":"2028-11-20","reading":"Ether 12–15","days":[{"d":"2028-11-20","ref":"Ether 12:6","b":"Ether","c":12,"v":6,"he":"וְעַתָּה אֲנִי מוֹרוֹנִי אֲדַבְּרָה מְעַט עַל־הַדְּבָרִים הָאֵלֶּה אַרְאֶה לָעוֹלָם כִּי הָאֱמוּנָה הִיא בַּדְּבָרִים הַמְקֻוִּים וְלֹא נִרְאִים לָכֵן אַל־תָּרִיבוּ כִּי־לֹא תִרְאוּ כִּי־לֹא תְקַבְּלוּ עֵדוּת עַד־אַחֲרֵי נִסְיוֹן אֱמוּנַתְכֶם׃","en":"And now, I, Moroni, would speak somewhat concerning these things; I would show unto the world that faith is things which are hoped for and not seen; wherefore, dispute not because ye see not, for ye receive no witness until after the trial of your faith."},{"d":"2028-11-21","ref":"Ether 12:27","b":"Ether","c":12,"v":27,"he":"וְכִי יָבֹאוּ אֵלַי בְּנֵי־אָדָם אַרְאֶה לָהֶם אֶת־חֻלְשָׁתָם נוֹתֵן אֲנִי לִבְנֵי־אָדָם חֻלְשָׁה לְמַעַן יִכָּנְעוּ וְדַי חַסְדִּי לְכׇל־הַנִּכְנָעִים לְפָנַי כִּי אִם־יִכָּנְעוּ לְפָנַי וְיַאֲמִינוּ בִי אָז אֶעֱשֶׂה לָהֶם חֻלְשׁוֹת לִגְבוּרוֹת׃","en":"And if men come unto me I will show unto them their weakness. I give unto men weakness that they may be humble; and my grace is sufficient for all men that humble themselves before me; for if they humble themselves before me, and have faith in me, then will I make weak things become strong unto them."},{"d":"2028-11-22","ref":"Ether 13:6","b":"Ether","c":13,"v":6,"he":"וְכִי תִּבָּנֶה יְרוּשָׁלַיִם חֲדָשָׁה בָּאָרֶץ הַזֹּאת לִשְׁאֵרִית זֶרַע יוֹסֵף אֲשֶׁר לַדְּבָרִים הָאֵלֶּה הָיָה מוֹפֵת׃","en":"And that a New Jerusalem should be built up upon this land, unto the remnant of the seed of Joseph, for which things there has been a type."},{"d":"2028-11-23","ref":"Ether 13:12","b":"Ether","c":13,"v":12,"he":"וּבְבוֹא הַדְּבָרִים הָאֵלֶּה יָקוּם הַכָּתוּב הָאוֹמֵר יֵשׁ רִאשׁוֹנִים אֲשֶׁר יִהְיוּ אַחֲרוֹנִים וְיֵשׁ אַחֲרוֹנִים אֲשֶׁר יִהְיוּ רִאשׁוֹנִים׃","en":"And when these things come, bringeth to pass the scripture which saith, there are they who were first, who shall be last; and there are they who were last, who shall be first."},{"d":"2028-11-24","ref":"Ether 14:21","b":"Ether","c":14,"v":21,"he":"וְכֹה גְדוֹלָה וַאֲרֻכָּה הָיְתָה הַמִּלְחָמָה וְכֹה אָרַךְ מַרְאֵה שְׁפֹךְ הַדָּמִים וְהַטֶּבַח עַד־כִּי כֻסְּתָה כׇל־פְּנֵי הָאָרֶץ בִּגְוִיּוֹת הַמֵּתִים׃","en":"And so great and lasting had been the war, and so long had been the scene of bloodshed and carnage, that the whole face of the land was covered with the bodies of the dead."},{"d":"2028-11-25","ref":"Ether 15:32","b":"Ether","c":15,"v":32,"he":"וַיְהִי כִּי־נָפַל כוֹרִיַנְטוּמְר אַרְצָה וַיְהִי כְּמֵת׃","en":"And it came to pass that Coriantumr fell to the earth, and became as if he had no life."},{"d":"2028-11-26","ref":"Ether 15:34","b":"Ether","c":15,"v":34,"he":"וְאֵלֶּה הַדְּבָרִים הָאַחֲרוֹנִים אֲשֶׁר כָּתַב אֶתֶר אִם־יִרְצֶה יְהוָה כִּי אֶנָּשֵׂא אוֹ כִּי אֶסְבֹּל אֶת־רְצוֹן יְהוָה בַּבָּשָׂר אֵין־דָּבָר אִם־רַק אִוָּשַׁע בְּמַלְכוּת הָאֱלֹהִים אָמֵן׃","en":"Now the last words which are written by Ether are these: Whether the Lord will that I be translated, or that I suffer the will of the Lord in the flesh, it mattereth not, if it so be that I am saved in the kingdom of God. Amen."}]});
